def _tiers():
    """-> list of tiers, each a list of rings, each a flat [x0, y0, x1, y1, ...]."""

    a = array("h")
    a.frombytes(zlib.decompress(base64.b64decode(_DATA)))

    if sys.byteorder == "big":
        a.byteswap()

    i = 1
    tiers = []

    for _ in range(a[0]):

        n_rings = a[i]
        i += 1
        rings = []

        for _ in range(n_rings):

            n = a[i]
            x, y = a[i + 1], a[i + 2]
            ring = [x, y]
            i += 3

            for _ in range(n - 1):
                x += a[i]
                y += a[i + 1]
                ring += (x, y)
                i += 2

            rings.append(ring)

        tiers.append(rings)

    return tiers


TIERS = _tiers()
